sysauto_script.script:
// ChangeCollision Radar — scheduled daily scan
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
(function runDailyScan() {
    var engine = new CollisionRadarEngine();
    var remediate = new CollisionRadarRemediate();

    var result = engine.scanCollisions();
    var flagged = remediate.flagForReview();
    var notified = remediate.notifyCAB();

    gs.info('x_snc_ccr daily scan complete: ' +
        result.scanned_changes + ' changes, ' +
        result.collisions + ' collisions, ' +
        result.freeze_violations + ' freeze violations, ' +
        result.risk_rows + ' risk rows, ' +
        flagged + ' flagged, ' +
        notified + ' notified');
})();
